परिशिष्टभागः - १
श्लोकार्धानुक्रमणिका
&lt;table&gt;&lt;thead&gt;&lt;tr&gt;&lt;th colspan="2"&gt;अ&lt;/th&gt;&lt;/tr&gt;&lt;/thead&gt;&lt;tbody&gt;&lt;tr&gt;&lt;td&gt;अ इत्याक्रियते यस्माद्&lt;/td&gt;&lt;td&gt;६८५&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;अंशेनोद्धृत्य रुद्राद्यैः&lt;/td&gt;&lt;td&gt;४८७&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;अकस्थितबृहत्याख्य&lt;/td&gt;&lt;td&gt;६७२&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;अकारः प्रथमं नाम&lt;/td&gt;&lt;td&gt;३७७&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;अकारनामा नान्योऽस्ति&lt;/td&gt;&lt;td&gt;३८६&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;अकारस्य तथोपांशो&lt;/td&gt;&lt;td&gt;३८२&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;अकारस्य विकारोऽयं&lt;/td&gt;&lt;td&gt;३८२&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;अकारार्था ह्यभावस्तु&lt;/td&gt;&lt;td&gt;४५१&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;अकारेण ततो विष्णुः&lt;/td&gt;&lt;td&gt;४५०&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;अकारेणैव तत्सर्व&lt;/td&gt;&lt;td&gt;३८३&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;अकारो वर्तते तेषा&lt;/td&gt;&lt;td&gt;४५१&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;अकृत्स्ना सा ततो नैव&lt;/td&gt;&lt;td&gt;३५६&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;अक्षण्वन्तो दर्शनाच्च&lt;/td&gt;&lt;td&gt;२३७&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;अक्षरादेव परमात्&lt;/td&gt;&lt;td&gt;४४१&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;अक्षि कण्ठो हृदित्येव&lt;/td&gt;&lt;td&gt;५०२&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;अगमद्देवलोकं हि&lt;/td&gt;&lt;td&gt;६४६&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;अग्निवातदिनेशानां&lt;/td&gt;&lt;td&gt;२२&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;अग्निश्च मित्रावरुणौ&lt;/td&gt;&lt;td&gt;४८&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;अग्निस्थमाश्रिता मर्त्या&lt;/td&gt;&lt;td&gt;१७&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;अग्निहोत्रादिके नित्य&lt;/td&gt;&lt;td&gt;३१८&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;अग्न्यादयस्ततः पश्चात्&lt;/td&gt;&lt;td&gt;५०१&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;अग्न्यादिषु च तन्नामा&lt;/td&gt;&lt;td&gt;२७&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;अग्नौ कर्माणि कृत्वैव&lt;/td&gt;&lt;td&gt;१७&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;अग्रजत्वाददित्यां&lt;/td&gt;&lt;td&gt;४०९&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;अग्र्य एव समस्तेभ्य&lt;/td&gt;&lt;td&gt;४८३&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;अग्र्यत्वात् सर्वभूतानाम्&lt;/td&gt;&lt;td&gt;६५५&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;अङ्गाङ्गित्वेनैक एव&lt;/td&gt;&lt;td&gt;२७&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;
771
&lt;table&gt;  &lt;tbody&gt;    &lt;tr&gt;      &lt;td&gt;अङ्गेभ्य एव सम्भूतान्य&lt;/td&gt;      &lt;td&gt;३५९&lt;/td&gt;    &lt;/tr&gt;    &lt;tr&gt;      &lt;td&gt;अङ्गेषु यस्य छन्दांसि&lt;/td&gt;      &lt;td&gt;१०१&lt;/td&gt;    &lt;/tr&gt;    &lt;tr&gt;      &lt;td&gt;अचिन्त्यविभवेऽप्य&lt;/td&gt;      &lt;td&gt;६९७&lt;/td&gt;    &lt;/tr&gt;    &lt;tr&gt;      &lt;td&gt;अचिन्त्यात् तु तथैश्वर्यात्&lt;/td&gt;      &lt;td&gt;९७&lt;/td&gt;    &lt;/tr&gt;    &lt;tr&gt;      &lt;td&gt;अच्छिद्रत्वं नैव सर्वैः&lt;/td&gt;      &lt;td&gt;७०४&lt;/td&gt;    &lt;/tr&gt;    &lt;tr&gt;      &lt;td&gt;अज्ञानतो ज्ञानतो&lt;/td&gt;      &lt;td&gt;६९७&lt;/td&gt;    &lt;/tr&gt;    &lt;tr&gt;      &lt;td&gt;अज्ञानदुःखसामर्थ्य&lt;/td&gt;      &lt;td&gt;६९७&lt;/td&gt;    &lt;/tr&gt;    &lt;tr&gt;      &lt;td&gt;अज्ञानादिप्रदातृत्वात्&lt;/td&gt;      &lt;td&gt;८७&lt;/td&gt;    &lt;/tr&gt;    &lt;tr&gt;      &lt;td&gt;अज्ञानाभिभवस्पृष्टा&lt;/td&gt;      &lt;td&gt;१७५&lt;/td&gt;    &lt;/tr&gt;    &lt;tr&gt;      &lt;td&gt;अज्ञानाभिभवास्पृष्टौ&lt;/td&gt;      &lt;td&gt;१७५&lt;/td&gt;    &lt;/tr&gt;    &lt;tr&gt;      &lt;td&gt;अण्डवन्मुखमस्यासीत्&lt;/td&gt;      &lt;td&gt;४८९&lt;/td&gt;    &lt;/tr&gt;    &lt;tr&gt;      &lt;td&gt;अण्डान्तः स्रष्टुमैच्छच्च&lt;/td&gt;      &lt;td&gt;४८७&lt;/td&gt;    &lt;/tr&gt;    &lt;tr&gt;      &lt;td&gt;अत इत्युच्यते विष्णुः&lt;/td&gt;      &lt;td&gt;७१४&lt;/td&gt;    &lt;/tr&gt;    &lt;tr&gt;      &lt;td&gt;अत इत्युच्यते विष्णुः&lt;/td&gt;      &lt;td&gt;७१४&lt;/td&gt;    &lt;/tr&gt;    &lt;tr&gt;      &lt;td&gt;अत एव पृथिव्यादि&lt;/td&gt;      &lt;td&gt;३१४&lt;/td&gt;    &lt;/tr&gt;    &lt;tr&gt;      &lt;td&gt;अतद्वशत्वं कस्यापि&lt;/td&gt;      &lt;td&gt;६९७&lt;/td&gt;    &lt;/tr&gt;    &lt;tr&gt;      &lt;td&gt;अतस्त्रिवृदिति प्रोक्त&lt;/td&gt;      &lt;td&gt;३३८&lt;/td&gt;    &lt;/tr&gt;    &lt;tr&gt;      &lt;td&gt;अतिनादात् सदा&lt;/td&gt;      &lt;td&gt;५४&lt;/td&gt;    &lt;/tr&gt;    &lt;tr&gt;      &lt;td&gt;अतिप्रियत्वाद्भगवान&lt;/td&gt;      &lt;td&gt;१८६&lt;/td&gt;    &lt;/tr&gt;    &lt;tr&gt;      &lt;td&gt;अत्तुं वागादिभिः&lt;/td&gt;      &lt;td&gt;४९७&lt;/td&gt;    &lt;/tr&gt;    &lt;tr&gt;      &lt;td&gt;अत्यल्पपुण्यभाक् स&lt;/td&gt;      &lt;td&gt;५४१&lt;/td&gt;    &lt;/tr&gt;    &lt;tr&gt;      &lt;td&gt;अथवा वायुदेवस्थं&lt;/td&gt;      &lt;td&gt;४६७&lt;/td&gt;    &lt;/tr&gt;    &lt;tr&gt;      &lt;td&gt;अदनाघ्राणदृष्ट्याख्य&lt;/td&gt;      &lt;td&gt;२४&lt;/td&gt;    &lt;/tr&gt;    &lt;tr&gt;      &lt;td&gt;अदोषत्वान्महाविष्णो&lt;/td&gt;      &lt;td&gt;१८८&lt;/td&gt;    &lt;/tr&gt;    &lt;tr&gt;      &lt;td&gt;अद्यापि तद्देवलोके&lt;/td&gt;      &lt;td&gt;५४८&lt;/td&gt;    &lt;/tr&gt;    &lt;tr&gt;      &lt;td&gt;अधरार्धस्य चोर्व्याश्च&lt;/td&gt;      &lt;td&gt;६०४&lt;/td&gt;    &lt;/tr&gt;    &lt;tr&gt;      &lt;td&gt;अधिकं ह्येव तस्मात्&lt;/td&gt;      &lt;td&gt;३१९&lt;/td&gt;    &lt;/tr&gt;    &lt;tr&gt;      &lt;td&gt;अधिकज्ञानलब्ध्यर्थं&lt;/td&gt;      &lt;td&gt;१९०&lt;/td&gt;    &lt;/tr&gt;    &lt;tr&gt;      &lt;td&gt;अधिकोच्चत्वमानं हि&lt;/td&gt;      &lt;td&gt;३८२&lt;/td&gt;    &lt;/tr&gt;    &lt;tr&gt;      &lt;td&gt;अधिकोच्चस्वरूपो&lt;/td&gt;      &lt;td&gt;३८३&lt;/td&gt;    &lt;/tr&gt;  &lt;/tbody&gt;&lt;/table&gt;

परिशिष्टभागः- १
&lt;table&gt;  &lt;tbody&gt;    &lt;tr&gt;      &lt;td&gt;आत्मेत्युक्तः स भगवान्&lt;/td&gt;      &lt;td&gt;६८८&lt;/td&gt;    &lt;/tr&gt;    &lt;tr&gt;      &lt;td&gt;आदानात् सर्वजीवाना&lt;/td&gt;      &lt;td&gt;६८८&lt;/td&gt;    &lt;/tr&gt;    &lt;tr&gt;      &lt;td&gt;आदानात् सर्ववस्तूनां&lt;/td&gt;      &lt;td&gt;१७&lt;/td&gt;    &lt;/tr&gt;    &lt;tr&gt;      &lt;td&gt;आदायान्तरधाद्यस्तु&lt;/td&gt;      &lt;td&gt;५४८&lt;/td&gt;    &lt;/tr&gt;    &lt;tr&gt;      &lt;td&gt;आदित्यमण्डलस्थश्च&lt;/td&gt;      &lt;td&gt;७१०&lt;/td&gt;    &lt;/tr&gt;    &lt;tr&gt;      &lt;td&gt;आदित्यसंस्थितो विष्णु&lt;/td&gt;      &lt;td&gt;१९३&lt;/td&gt;    &lt;/tr&gt;    &lt;tr&gt;      &lt;td&gt;आदित्या वसवो रुद्रा&lt;/td&gt;      &lt;td&gt;४६३&lt;/td&gt;    &lt;/tr&gt;    &lt;tr&gt;      &lt;td&gt;आदित्यादिषु च स्थित्वा&lt;/td&gt;      &lt;td&gt;६८८&lt;/td&gt;    &lt;/tr&gt;    &lt;tr&gt;      &lt;td&gt;आदित्ये संस्थितो&lt;/td&gt;      &lt;td&gt;४१३&lt;/td&gt;    &lt;/tr&gt;    &lt;tr&gt;      &lt;td&gt;आदित् प्रत्नस्येति विष्णुः&lt;/td&gt;      &lt;td&gt;७१०&lt;/td&gt;    &lt;/tr&gt;    &lt;tr&gt;      &lt;td&gt;आद्यो भवति चान्येषां&lt;/td&gt;      &lt;td&gt;३०&lt;/td&gt;    &lt;/tr&gt;    &lt;tr&gt;      &lt;td&gt;आधारः सर्ववेदानां&lt;/td&gt;      &lt;td&gt;५८३&lt;/td&gt;    &lt;/tr&gt;    &lt;tr&gt;      &lt;td&gt;आधिक्यं कुत एव&lt;/td&gt;      &lt;td&gt;४४९&lt;/td&gt;    &lt;/tr&gt;    &lt;tr&gt;      &lt;td&gt;आधिक्यं छन्दसां यत्र&lt;/td&gt;      &lt;td&gt;३६१&lt;/td&gt;    &lt;/tr&gt;    &lt;tr&gt;      &lt;td&gt;आधिक्यं ज्ञायते&lt;/td&gt;      &lt;td&gt;२६१&lt;/td&gt;    &lt;/tr&gt;    &lt;tr&gt;      &lt;td&gt;आधिक्यार्थे मय&lt;/td&gt;      &lt;td&gt;३३&lt;/td&gt;    &lt;/tr&gt;    &lt;tr&gt;      &lt;td&gt;आप इत्येव देवानां&lt;/td&gt;      &lt;td&gt;८१&lt;/td&gt;    &lt;/tr&gt;    &lt;tr&gt;      &lt;td&gt;आप इत्येव देवानां&lt;/td&gt;      &lt;td&gt;८०&lt;/td&gt;    &lt;/tr&gt;    &lt;tr&gt;      &lt;td&gt;आप इत्येव नामैषां&lt;/td&gt;      &lt;td&gt;८०&lt;/td&gt;    &lt;/tr&gt;    &lt;tr&gt;      &lt;td&gt;आपरोक्ष्यं भवेद् यस्मा&lt;/td&gt;      &lt;td&gt;७१&lt;/td&gt;    &lt;/tr&gt;    &lt;tr&gt;      &lt;td&gt;आपूरयन्सर्वलोकान्&lt;/td&gt;      &lt;td&gt;६८८&lt;/td&gt;    &lt;/tr&gt;    &lt;tr&gt;      &lt;td&gt;आप्नुवन्ति मनुष्येषु&lt;/td&gt;      &lt;td&gt;७०३&lt;/td&gt;    &lt;/tr&gt;    &lt;tr&gt;      &lt;td&gt;आप्नुवन्ति सुराः सर्वे&lt;/td&gt;      &lt;td&gt;४३८&lt;/td&gt;    &lt;/tr&gt;    &lt;tr&gt;      &lt;td&gt;आप्नोत्यत्र स्वयं विष्ण&lt;/td&gt;      &lt;td&gt;५०२&lt;/td&gt;    &lt;/tr&gt;    &lt;tr&gt;      &lt;td&gt;आयन् सर्वेषु लोकेषु&lt;/td&gt;      &lt;td&gt;७२२&lt;/td&gt;    &lt;/tr&gt;    &lt;tr&gt;      &lt;td&gt;आयातमिति हैवैतौ&lt;/td&gt;      &lt;td&gt;४६७&lt;/td&gt;    &lt;/tr&gt;    &lt;tr&gt;      &lt;td&gt;आयुःशब्दो ज्ञानवाची&lt;/td&gt;      &lt;td&gt;४९८&lt;/td&gt;    &lt;/tr&gt;    &lt;tr&gt;      &lt;td&gt;आयुरूपोऽखिलानां&lt;/td&gt;      &lt;td&gt;४९८&lt;/td&gt;    &lt;/tr&gt;    &lt;tr&gt;      &lt;td&gt;आवासस्थानमुद्दिष्टो&lt;/td&gt;      &lt;td&gt;३३&lt;/td&gt;    &lt;/tr&gt;    &lt;tr&gt;      &lt;td&gt;आविर्भावं तारतम्यात्&lt;/td&gt;      &lt;td&gt;३००&lt;/td&gt;    &lt;/tr&gt;  &lt;/tbody&gt;&lt;/table&gt;
